INSERT INTO public.source (id, title, source_type, author, edition, url, note)
SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "旧五代史·卷一百〇一", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/a2b6b6c94d54b9864bcd3d22174bace805c3e93e/content/books/zizhi-tongjian/vol-288/year-0948/part-08/sources/library/jiuwudaishi-101-november-948/source.txt", "note": "《旧五代史》卷一百〇一，段落 jiu-wudaishi-205deb4a7860-p002461；EPUB电子本，纸本及异文待核", "id": "a3ad3d6a-7b41-5245-a428-60d4362aa49d"}, {"title": "旧五代史·卷一百〇一", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/a2b6b6c94d54b9864bcd3d22174bace805c3e93e/content/books/zizhi-tongjian/vol-288/year-0948/part-08/sources/library/jiuwudaishi-101-october-948/source.txt", "note": "《旧五代史》卷一百〇一，段落 jiu-wudaishi-205deb4a7860-p002460；EPUB电子本，纸本及异文待核", "id": "87882d1e-9255-5ad4-8ca0-ea412d6b7078"}, {"title": "旧五代史·卷一百〇八", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/a2b6b6c94d54b9864bcd3d22174bace805c3e93e/content/books/zizhi-tongjian/vol-288/year-0948/part-08/sources/library/jiuwudaishi-108-li-song-estate/source.txt", "note": "《旧五代史》卷一百〇八，段落 jiu-wudaishi-205deb4a7860-p002588；EPUB电子本，纸本及异文待核", "id": "5b02a7fc-c9dd-5907-8cfc-e1c81f8d9a36"}, {"title": "新五代史·卷五十三", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/a2b6b6c94d54b9864bcd3d22174bace805c3e93e/content/books/zizhi-tongjian/vol-288/year-0948/part-08/sources/library/xinwudaishi-053-wang-fengxiang-siege/source.txt", "note": "《新五代史》卷五十三，段落 xin-wudaishi-b08f244b9241-p002067；EPUB电子本，纸本及异文待核", "id": "b05cde43-0fd0-5a1a-8994-81365a6f1a6c"}, {"title": "新五代史·卷六十四", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/a2b6b6c94d54b9864bcd3d22174bace805c3e93e/content/books/zizhi-tongjian/vol-288/year-0948/part-08/sources/library/xinwudaishi-064-shu-relief-948/source.txt", "note": "《新五代史》卷六十四，段落 xin-wudaishi-b08f244b9241-p003240；EPUB电子本，纸本及异文待核", "id": "438b8ad3-4471-55f2-8e6c-09c997de13d2"}, {"title": "资治通鉴·后汉纪三", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/cfc4e70dd5b944e6aa97489ccdc694e25f795d09/content/books/zizhi-tongjian/vol-288/year-0948/part-07/sources/library/tongjian-288-948-september-october/source.txt", "note": "《资治通鉴》后汉纪三，段落 zizhi-tongjian-a63549944a71-p003419；电子底本待考，分段待核", "id": "5dd92625-5b82-53e2-a934-748b7c57b05d"}, {"title": "新五代史·卷十一", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/e4f57a30a26d134a760f4628c87dbbe735d6f3c2/content/books/zizhi-tongjian/vol-288/year-0948/part-06/sources/library/xinwudaishi-011-guo-rewards/source.txt", "note": "《新五代史》卷十一，段落 xin-wudaishi-b08f244b9241-p000362；EPUB电子本，纸本及异文待核", "id": "44daf767-2198-5790-9d76-d57b75bf536c"}, {"title": "新五代史·卷六十九", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/5047247441ba8ca5148602bf0116a6c308eb295b/content/books/zizhi-tongjian/vol-288/year-0948/part-05/sources/library/xinwudaishi-069-gao-renews-tribute/source.txt", "note": "《新五代史》卷六十九，段落 xin-wudaishi-b08f244b9241-p003433；EPUB电子本，纸本及异文待核", "id": "32010df6-310e-56ac-8a89-a6fac5ee7175"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "李守贞", "aliases": ["李守貞"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋内客省使。940年五月受命担任马全节讨伐李金全军队的都监，职务由《旧五代史》本纪补充。生卒年未据本段确定。", "biography": null, "status": "draft", "id": "a3d16959-684f-5c82-b848-8dcbdc73e85a"}, {"name": "总伦", "aliases": ["總倫"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "李守贞门下僧人，以方术预言李守贞将成为皇帝，受到其相信。《新五代史》也记总伦以方术影响李守贞，预言均按说话者的主张记录。生卒年未载。", "biography": null, "status": "draft", "id": "079788d1-e6b4-52de-b2df-58b27472ca5f"}, {"name": "王景崇", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋官员。937年担任引进使，受命劝秘琼接受任命。史书记载他是邢州人。", "biography": null, "status": "draft", "id": "5f673eda-0daa-5174-926f-dca3e0982614"}, {"name": "王德让", "aliases": ["王德讓"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "王景崇之子。948年十月奉父亲之命到成都见孟昶。生卒年及其他经历未据本段确定。", "biography": null, "status": "draft", "id": "aa4a724b-190a-58a1-a190-611072f37f0d"}, {"name": "孟昶", "aliases": ["孟仁赞", "孟仁贊"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275天成二年条所见人物：孟昶，孟子、被迎者。", "biography": null, "status": "draft", "id": "666201f7-9186-590e-8d5b-2a4a605dba69"}, {"name": "赵思绾", "aliases": ["趙思綰"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "魏州人，原在赵在礼军中，后来成为赵匡赞牙将。948年王景崇试图令赵匡赞牙兵刺面防逃时，主动提出先刺自己以率众。齐藏珍建议将其杀死，王景崇不听。生卒年尚未录入。", "biography": null, "status": "draft", "id": "b571162d-9596-5439-a443-f33cd87ea628"}, {"name": "赵怀乂", "aliases": ["趙懷乂"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "赵思绾之子。948年十月奉父亲之命到成都见孟昶。生卒年及其他经历未据本段确定。", "biography": null, "status": "draft", "id": "276a9f32-d072-5d0a-afdf-b667f81f8922"}, {"name": "赵晖", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷257光启三年条所见人物：赵晖。", "biography": null, "status": "draft", "id": "9efd6fe6-4ba6-5e2b-99cc-751822d75039"}, {"name": "安思谦", "aliases": ["安思謙"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：安思谦，茶酒库使、曾事藩邸者。", "biography": null, "status": "draft", "id": "6ec752d6-91f9-5760-8ea8-c552e6369345"}, {"name": "毋昭裔", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：毋昭裔，龙门人、原御史中丞、获任宰辅者。", "biography": null, "status": "draft", "id": "4d43c16a-22c8-593d-ba83-347e273efd9a"}, {"name": "韩保贞", "aliases": ["韓保貞"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：韩保贞，丰德库使、曾事藩邸者。", "biography": null, "status": "draft", "id": "7090cd80-1efa-59ab-9b8f-05f88da57d52"}, {"name": "李彦舜", "aliases": ["李彥舜"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "酸枣人，曾任义成节度使。948年十月王景崇派他等人迎接后蜀援军。生卒年未载。", "biography": null, "status": "draft", "id": "e4344742-c6ae-54b6-bc1c-51e1952cd963"}, {"name": "申贵", "aliases": ["申貴"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "潞州人，后蜀眉州刺史。948年十月奉安思谦命率二千兵前往模壁，在竹林设伏；丁酉早晨用数百兵在宝鸡前列阵，引诱后汉兵追击。后汉兵中伏败退，蜀军追击并攻破宝鸡寨。生卒年未载。", "biography": null, "status": "draft", "id": "0a0e0938-9bfd-5f40-a478-e6c2b3eead34"}, {"name": "高从诲", "aliases": ["高從誨"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷273同光三年条所见人物：高从诲。", "biography": null, "status": "draft", "id": "361de308-8df0-56e4-ac98-81f6b9297e26"}, {"name": "高保融", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "高从诲之子，荆南节度副使。948年十月父亲病重时，受命管理内外兵马事务；高从诲去世后，以留后身份暂掌军府。《新五代史》记他是高从诲的第三子。生卒年尚未确定。", "biography": null, "status": "draft", "id": "88e76c46-c48c-5103-9a49-99e0b54eed61"}, {"name": "李彝殷", "aliases": ["李彜殷", "李彝兴", "李彝興"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：李彝殷，行军司马、权知军州事者。", "biography": null, "status": "draft", "id": "22edc111-ae26-5bce-a26b-3ae072425377"}, {"name": "高允权", "aliases": ["高允權"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "高万金之子。947年延州军队攻周密，高允权获推为留后、据西城。《通鉴》称录事参军，《新五代史》追记开运时任肤施令、罢后居家，任职时点及写法分别保留。生卒年暂未录入。", "biography": null, "status": "draft", "id": "be6f380e-7cd3-5e5e-87d2-900104d55f65"}, {"name": "刘知远", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷271贞明五年条所见人物：刘知远。", "biography": null, "status": "draft", "id": "69fa3b4b-2f0d-5799-bbf5-e378af9816e1"}, {"name": "冯道", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷268乾化元年条所见人物：冯道。", "biography": null, "status": "draft", "id": "16b195e8-f15a-5814-bdd2-934f10bbdf39"}, {"name": "苏禹珪", "aliases": ["蘇禹珪"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "密州人，任河东观察判官。947年刘知远任命他为中书侍郎、同平章事。具体生卒年尚未录入。", "biography": null, "status": "draft", "id": "b8c912f3-4f5e-5fbc-9714-9caaf03ed98c"}, {"name": "李崧", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷274同光四年条所见人物：李崧。", "biography": null, "status": "draft", "id": "42727c37-29c7-534f-b0f7-900992c16def"}, {"name": "苏逢吉", "aliases": ["蘇逢吉"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "长安人，任河东节度判官。947年刘知远任命他为中书侍郎、同平章事。具体生卒年尚未录入。", "biography": null, "status": "draft", "id": "1136d429-42fd-5166-94a0-f2dd9af9c920"}, {"name": "李屿", "aliases": ["李嶼"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "李崧的弟弟，后汉朝官。李崧旧宅被苏逢吉占有后，李屿与李崧的另一位弟弟李㠖饮酒时曾表达怨言，苏逢吉因此对李崧一方生怨。生卒年及具体官职尚未录入。", "biography": null, "status": "draft", "id": "3c5f9b7a-188d-5885-adb8-894048d9374b"}, {"name": "李㠖", "aliases": ["李嶬"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "李崧的弟弟，后汉朝官，与李屿饮酒时曾对家产被占表达怨言。《旧五代史》同段记㠖，本纪另写嶬；《通鉴》电子底本用山、义的组合占位表示名字。生卒年及具体官职尚未录入。", "biography": null, "status": "draft", "id": "a55e6acb-2f09-5fda-96df-e4a0f280616a"}, {"name": "陶谷", "aliases": ["陶穀"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后汉翰林学士，曾受李崧引荐。《资治通鉴》在李崧遭苏逢吉排挤的背景中记陶谷也加入诬陷。姓名谷、穀按繁简匹配，生卒年尚未录入。", "biography": null, "status": "draft", "id": "7d8e6fa9-c77d-5157-b782-a59c82d864be"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

